    23	function fillStationsAndBikes(database: Database) {
    24	  const addStation = database.prepare("INSERT INTO stations VALUES (?, ?, ?, ?, ?, ?, ?)");
    25	  for (const station of readCsv(join(DATA_FOLDER, "stations.csv"))) {
    26	    const mapPosition = [Number(station.x), Number(station.y)];
    27	    const where = [station.station_id, station.name, station.district, station.depot];
    28	    addStation.run(...where, ...mapPosition, Number(station.docks));
    29	  }
